-- 0030 : programme des carnets de stage sur les bases existantes.
-- Strictement additif : fusionne l'union des services et des 2 filières aux
-- carnets (jamais de suppression) et crée `service_heures` + `programme_stages`
-- uniquement si absents. Les 6 hôpitaux et les autres réglages sont intouchés.
--> statement-breakpoint
UPDATE "settings"
SET "value" = (
  SELECT COALESCE(jsonb_agg(e ORDER BY e), '[]'::jsonb)
  FROM (
    SELECT DISTINCT e FROM (
      SELECT jsonb_array_elements_text("value") AS e FROM "settings" WHERE "key" = 'filieres'
      UNION
      SELECT unnest(ARRAY['Aide-Soignant(e)', 'Infirmier(e) Auxiliaire'])
    ) u
  ) s(e)
)
WHERE "key" = 'filieres';
--> statement-breakpoint
UPDATE "settings"
SET "value" = (
  SELECT COALESCE(jsonb_agg(e ORDER BY e), '[]'::jsonb)
  FROM (
    SELECT DISTINCT e FROM (
      SELECT jsonb_array_elements_text("value") AS e FROM "settings" WHERE "key" = 'services_stage'
      UNION
      SELECT unnest(ARRAY['Bloc opératoire', 'Bloc opératoire gynéco-obstétrical', 'Cardiologie', 'CDTRM', 'Centre de référence', 'Chirurgie', 'Chirurgie + Stérilisation', 'Consultation gynécologique (MST)', 'Consultation postnatale et enfants', 'Dermatologie', 'FVAD (enfants)', 'Gynécologie', 'Maison d''accouchement', 'Maison d''accouchement rurale', 'Maternité', 'Maternité + maison d''accouchement', 'Médecine', 'Obstétrique', 'Ophtalmologie', 'ORL', 'Pédiatrie', 'Pédiatrie périnatale', 'Pédiatrie-Crèche', 'Planification familiale (PF)', 'Réanimation', 'Réanimation chirurgicale', 'Réanimation gynéco-obstétricale', 'Réanimation médicale', 'Salle d''admission (jour)', 'Salle d''admission (nuit)', 'Salle de travail et accouchement (jour)', 'Salle de travail et accouchement (nuit)', 'SMI', 'SMI (prénatal, PF, visites à domicile)', 'SMT', 'Soins de santé de base', 'Stage optionnel', 'Stage rural', 'Stérilisation', 'Suites de couches', 'Urgences', 'Urgences gynéco-obstétricales', 'Uro-néphrologie (hémodialyse)'])
    ) u
  ) s(e)
)
WHERE "key" = 'services_stage';
--> statement-breakpoint
